  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 10px;
  letter-spacing: 5px;
  color: white;
  opacity: 0;
  transition: all 1s cubic-bezier(0.895, 0.03, 0.685, 0.22);
}
